  var kpK  = cl(nn(P.kpK, 600), 60, 1800);
  var kdK  = cl(nn(P.kdK, 55), 4, 220);
  var g1   = cl(nn(P.g1, 0.85), -1.5, 2.5);
  var g2   = cl(nn(P.g2, 0.20), -1.0, 0.9);
  var krt  = cl(nn(P.krt, 110), -700, 700);
  var krw  = cl(nn(P.krw, 45), -350, 350);
  var lean = cl(nn(P.lean, -0.03), -0.45, 0.45);
  var kvs  = cl(nn(P.kvs, 0.5), -1.0, 3.0);
  var ktL  = cl(nn(P.ktL, 1.1), -1.0, 3.0);
  var ktY  = cl(nn(P.ktY, 0.8), -0.6, 1.5);
  var push = cl(nn(P.push, 0.20), -1.0, 1.0);
  var fh   = (nn(P.fh, 1) >= 0) ? 1 : -1;
  var fk   = (nn(P.fk, 1) >= 0) ? 1 : -1;

  var ta   = nn(obs[0], 0);
  var tsp  = nn(obs[1], 0);
  var vx   = nn(obs[2], 0);
  var qhA  = fh * nn(obs[5], 0),  qhsA = fh * nn(obs[6], 0);
  var qkA  = fk * nn(obs[7], 0),  qksA = fk * nn(obs[8], 0);
  var qhB  = fh * nn(obs[10], 0), qhsB = fh * nn(obs[11], 0);
  var qkB  = fk * nn(obs[12], 0), qksB = fk * nn(obs[13], 0);
  var a1   = nn(obs[15], 0), a2 = nn(obs[16], 0);
