    var o = {};
    for (var i = 0; i < n; i++) {
      var uu = cl(vec[i], -1, 1);
      o[names[i]] = lo[i] + (hi[i] - lo[i]) * (uu * 0.5 + 0.5);
    }
    o.fh = fhv; o.fk = fkv;
    return o;
