    const x = candidate.map(reflect);
    let r = null;
    try {
      r = lab.trial(x.slice());
    } catch (e) {
      r = null;
    }
    used++;

    let distance =
      r && typeof r.distance === "number" && isFinite(r.distance)
        ? r.distance
        : -1000;
    let time =
      r && typeof r.time === "number" && isFinite(r.time)
        ? clamp(r.time, 0, 10)
        : 0;
    const outcome = r && r.outcome;
    if (outcome === "finished" && time === 0) time = 10;

    let fitness = distance + 0.08 * time;
    if (outcome === "finished") fitness += 0.30;
    if (outcome === "invalid" || outcome === "error" || !r) {
      fitness = -100000;
    }

    const item = { x: x, f: fitness };
    if (!best || item.f > best.f) best = { x: x.slice(), f: fitness };
    return item;
  }

  const budget = remaining();
  if (budget <= 0) return base;
  const popSize = Math.min(40, budget);
  const pop = [];

  function initialCandidate(i) {
    if (i < seeds.length) return seeds[i].slice();

    if (seeds.length > 0 && i < Math.floor(popSize * 0.76)) {
      const origin = seeds[Math.floor(Math.random() * seeds.length)];
      const sigma = 0.18 + 0.27 * Math.random();
      const x = new Array(dim);
      for (let j = 0; j < dim; j++) {
        const scale = j === 5 ? 0.55 : (j === 2 ? 0.85 : 1);
        x[j] = reflect(origin[j] + sigma * scale * normal());
      }
      return x;
    }

    const x = new Array(dim);
    for (let j = 0; j < dim; j++) x[j] = 2 * Math.random() - 1;
    return x;
  }

  for (let i = 0; i < popSize && remaining() > 0; i++) {
    pop.push(evaluate(initialCandidate(i)));
  }

  let iter = 0;
  while (remaining() > 0 && pop.length >= 4) {
    const targetIndex = iter % pop.length;
    const target = pop[targetIndex];

    const chosen = [targetIndex];
    const pick = () => {
      let j;
      do {
        j = Math.floor(Math.random() * pop.length);
      } while (chosen.indexOf(j) >= 0);
      chosen.push(j);
      return j;
    };
    const r1 = pick();
    const r2 = pick();
    const r3 = pick();
    const F = 0.42 + 0.46 * Math.random();
    const CR = 0.65 + 0.32 * Math.random();
    const mode = Math.random();
    const restart = mode < 0.05;
    const mutant = new Array(dim);

    if (restart) {
      for (let j = 0; j < dim; j++) mutant[j] = 2 * Math.random() - 1;
    } else {
      for (let j = 0; j < dim; j++) {
        if (mode < 0.50) {
          mutant[j] = pop[r1].x[j] + F * (pop[r2].x[j] - pop[r3].x[j]);
        } else if (mode < 0.82) {
          mutant[j] =
            target.x[j] +
            F * (best.x[j] - target.x[j]) +
            F * (pop[r1].x[j] - pop[r2].x[j]);
        } else {
          mutant[j] = best.x[j] + F * (pop[r1].x[j] - pop[r2].x[j]);
        }
      }
    }

    const forced = Math.floor(Math.random() * dim);
    const child = new Array(dim);
    for (let j = 0; j < dim; j++) {
      child[j] = restart || Math.random() < CR || j === forced
        ? reflect(mutant[j])
        : target.x[j];
    }

    const result = evaluate(child);
    if (
      result.f > target.f + 1e-10 ||
      (Math.abs(result.f - target.f) <= 1e-10 && Math.random() < 0.04)
    ) {
      pop[targetIndex] = result;
    }
    iter++;
  }

  return best ? best.x.slice() : base;
}

function policy(obs, params, mem) {
  if (!obs) obs = [];
  if (!mem || typeof mem !== "object") mem = {};

  const clamp = (x, lo, hi) => Math.max(lo, Math.min(hi, x));
  const fract = (x) => x - Math.floor(x);
  const smooth = (x) => {
    x = clamp(x, 0, 1);
    return x * x * (3 - 2 * x);
  };
  const read = (i) => {
    const x = obs[i];
    return typeof x === "number" && isFinite(x) ? x : 0;
  };
  const z = params && typeof params.length === "number" ? params : [];
  const dec = (i, lo, hi, fallback) => {
    const x = z[i];
    if (typeof x !== "number" || !isFinite(x)) return fallback;
    return lo + 0.5 * (clamp(x, -1, 1) + 1) * (hi - lo);
  };

  const period = dec(0, 0.45, 0.95, 0.64);
  const duty = dec(1, 0.46, 0.75, 0.60);
  const phase0 = dec(2, 0, 1, 0.03);
  const phaseGap = dec(3, 0.42, 0.58, 0.50);
  const center = dec(4, -0.28, 0.28, 0.02);
  const amp = dec(5, -0.90, 0.90, 0.65);
  const kneeStance = dec(6, -0.45, -0.05, -0.14);
  const kneeFlex = dec(7, -1.68, -0.35, -1.25);
  const hipKp = dec(8, 1.0, 8.0, 4.5);
  const hipKd = dec(9, 0.05, 1.15, 0.50);
  const kneeKp = dec(10, 1.0, 8.0, 4.5);
  const kneeKd = dec(11, 0.05, 1.15, 0.45);
  const balanceKp = dec(12, 0.25, 1.55, 0.90);
  const balanceKd = dec(13, 0.05, 0.85, 0.30);
  const leanAim = dec(14, -0.10, 0.10, -0.03);
  const leanSpeed = dec(15, 0, 0.12, 0.05);
  const velocityFeed = dec(16, 0.20, 0.95, 0.65);
  const startup = dec(17, 0, 0.30, 0.10);
  const swingBodyFollow = dec(18, 0, 0.80, 0.25);
  const supportBias = dec(19, 0, 1, 0.55);
  const contactBlend = dec(20, 0, 1, 0.35);
  const obstacleKnee = dec(21, 0, 4.5, 2.8);
  const obstacleHip = dec(22, 0, 1.8, 0.6);
  const strideAdapt = dec(23, 0, 0.65, 0.20);
  const targetSpeed = dec(24, 0.20, 1.20, 0.80);
  const recoveryGain = dec(25, 0, 1.5, 0.35);

  const torsoAngle = read(0);
  const torsoSpin = read(1);
  const vx = read(2);
  const hipA = read(5);
  const hipASpeed = read(6);
  const kneeA = read(7);
  const kneeASpeed = read(8);
  const footA = read(9) > 0.5;
  const hipB = read(10);
  const hipBSpeed = read(11);
  const kneeB = read(12);
  const kneeBSpeed = read(13);
  const footB = read(14) > 0.5;
  const t = Math.max(0, read(19));

  const speedError = clamp(targetSpeed - vx, -1.2, 1.2);
  const strideScale = clamp(1 + strideAdapt * speedError, 0.55, 1.55);
  const effectiveAmp = amp * strideScale;
  const hipFront = clamp(center + effectiveAmp, -0.88, 1.18);
  const hipBack = clamp(center - effectiveAmp, -0.88, 1.18);
  const hipDirection = effectiveAmp < 0 ? -1 : 1;
