  const desiredLean = clamp(
    leanAim - leanSpeed * (1.0 - clamp(vx, -1.0, 2.5)),
    -0.22,
    0.22
  );

  let dt = 1 / 60;
  let pa, pb;
  if (mem._gInit !== 1) {
    pa = fract(phase0 + t / effectivePeriod);
    pb = fract(phase0 + phaseGap + t / effectivePeriod);

    mem._gStartHA = hipA;
    mem._gStartKA = kneeA;
    mem._gStartHB = hipB;
    mem._gStartKB = kneeB;
  } else {
    let elapsed = t - mem._gT;
    if (!(elapsed > 0) || !isFinite(elapsed)) elapsed = 1 / 60;
