  mem._gInit = 1;
  mem._gPA = pa;
  mem._gPB = pb;
  mem._gT = t;
  mem._gFootA = footA;
  mem._gFootB = footB;

  function targets(p, foot) {
    let h, k;
    if (p < duty) {
      const u = clamp(p / duty, 0, 1);
      const e = smooth(u);
      h = hipFront + (hipBack - hipFront) * e;
      k = kneeStance;
    } else {
      const u = clamp((p - duty) / (1 - duty), 0, 1);
      const s = Math.sin(Math.PI * u);
      const lift = s * s;
      h = hipBack + (hipFront - hipBack) * smooth(u);
      k = kneeStance + (kneeFlex - kneeStance) * lift;

      h += hipDirection * obstacleHip * hazard * lift;
      k -= obstacleKnee * hazard * lift;
      h += swingBodyFollow *
        clamp(desiredLean - torsoAngle, -0.5, 0.5) * lift;

      if (foot) {
        const alpha = contactBlend * smooth((u - 0.05) / 0.70);
        k += (kneeStance - k) * alpha;
      }
    }
    return [
      clamp(h, -0.88, 1.18),
      clamp(k, -1.68, -0.06)
    ];
  }

  const refA = targets(pa, footA);
  const refB = targets(pb, footB);
  const ramp = startup > 0.001 ? smooth(t / startup) : 1;

  const targetHA = mem._gStartHA + ramp * (refA[0] - mem._gStartHA);
  const targetKA = mem._gStartKA + ramp * (refA[1] - mem._gStartKA);
  const targetHB = mem._gStartHB + ramp * (refB[0] - mem._gStartHB);
  const targetKB = mem._gStartKB + ramp * (refB[1] - mem._gStartKB);

  let vHA = 0, vKA = 0, vHB = 0, vKB = 0;
  if (mem._gHasTargets === 1) {
    vHA = clamp((targetHA - mem._gPrevHA) / dt, -8, 8);
    vKA = clamp((targetKA - mem._gPrevKA) / dt, -8, 8);
    vHB = clamp((targetHB - mem._gPrevHB) / dt, -8, 8);
    vKB = clamp((targetKB - mem._gPrevKB) / dt, -8, 8);
  }
  mem._gHasTargets = 1;
  mem._gPrevHA = targetHA;
  mem._gPrevKA = targetKA;
  mem._gPrevHB = targetHB;
  mem._gPrevKB = targetKB;

  const angleError = clamp(torsoAngle - desiredLean, -1.5, 1.5);
  let balance =
    balanceKp * angleError +
    balanceKd * clamp(torsoSpin, -10, 10);

  if (!footA && !footB) balance *= 0.70;
  const severity = clamp((Math.abs(angleError) - 0.18) / 0.70, 0, 1);
  balance *= 1 + recoveryGain * severity;
  balance = clamp(balance, -0.95, 0.95);

  const stanceA = pa < duty;
  const stanceB = pb < duty;
  const wa = 0.25 + supportBias *
    (footA ? 1.0 : (stanceA ? 0.42 : 0.08));
  const wb = 0.25 + supportBias *
    (footB ? 1.0 : (stanceB ? 0.42 : 0.08));
  const balanceScale = 2 / Math.max(0.01, wa + wb);
  const balanceA = balance * wa * balanceScale;
  const balanceB = balance * wb * balanceScale;

  const uHA =
    hipKp * (targetHA - hipA) +
    hipKd * (velocityFeed * vHA - hipASpeed) +
    balanceA;
  const uKA =
    kneeKp * (targetKA - kneeA) +
    kneeKd * (velocityFeed * vKA - kneeASpeed);
  const uHB =
    hipKp * (targetHB - hipB) +
    hipKd * (velocityFeed * vHB - hipBSpeed) +
    balanceB;
  const uKB =
    kneeKp * (targetKB - kneeB) +
    kneeKd * (velocityFeed * vKB - kneeBSpeed);

  return [
    clamp(uHA, -1, 1),
    clamp(uKA, -1, 1),
    clamp(uHB, -1, 1),
    clamp(uKB, -1, 1)
  ];
}

