  const balanceKd = dec(11, 0.03, 0.95, 0.35);
  const leanAim = dec(12, -0.10, 0.06, -0.035);
  const velocityFeed = dec(13, 0.20, 0.95, 0.55);
  const targetSpeed = dec(14, 0.25, 1.25, 0.75);
  const strideAdapt = dec(15, 0, 0.38, 0.16);
  const catchGain = dec(16, 0, 0.85, 0.35);
