    pa = fract(mem._gPA + dt / effectivePeriod);
    pb = fract(mem._gPB + dt / effectivePeriod);

    if (footA && !mem._gFootA && t > 0.08 && pa > duty - 0.12) pa = 0;
    if (footB && !mem._gFootB && t > 0.08 && pb > duty - 0.12) pb = 0;
