    } else {
      targetIndex = pop.indexOf(ranked[ranked.length - 1]);
      if (targetIndex < 0) targetIndex = iter % pop.length;
      candidate = new Array(dim);
      for (let j = 0; j < dim; j++) {
        candidate[j] = 2 * Math.random() - 1;
      }
    }

    const result = evaluate(candidate);
    if (
      result.f > pop[targetIndex].f + 1e-10 ||
      (Math.abs(result.f - pop[targetIndex].f) <= 1e-10 &&
        Math.random() < 0.02)
    ) {
      pop[targetIndex] = result;
    }

    sinceBest = best && best.f > previousBest + 1e-10
      ? 0
      : sinceBest + 1;
    iter++;
  }

  return best ? best.x.slice() : encode(base);
}

function policy(obs, params, mem) {
