  const kneeStance = dec(4, -0.22, -0.035, -0.12);
  const kneeFlex = dec(5, -1.68, -0.65, -1.35);
  const hipKp = dec(6, 1.5, 6.2, 4.2);
  const hipKd = dec(7, 0.08, 0.95, 0.42);
  const kneeKp = dec(8, 1.5, 6.5, 4.1);
  const kneeKd = dec(9, 0.08, 0.95, 0.42);
  const balanceKp = dec(10, 0.35, 4.5, 2.4);
  const balanceKd = dec(11, 0.08, 1.8, 0.70);
