  const velocityFeed = dec(13, 0.20, 1.0, 0.68);
  const targetSpeed = dec(14, 0.25, 1.35, 0.78);
  const strideAdapt = dec(15, 0, 0.50, 0.18);
  const catchGain = dec(16, 0, 1.0, 0.48);
  const supportBias = dec(17, 0, 1.0, 0.65);
  const obstacleKnee = dec(18, 0, 5.5, 4.0);
  const obstacleHip = dec(19, 0, 1.0, 0.45);
  const contactBlend = dec(20, 0, 1.0, 0.42);
  const heightGain = dec(21, 0, 0.8, 0.38);
  const heightDamp = dec(22, 0, 0.12, 0.04);
  const recoveryPriority = dec(23, 0, 1.5, 1.0);
  const phaseOffset = dec(24, 0, 0.12, 0.025);

  const torsoAngle = read(0);
  const torsoSpin = read(1);
  const vx = read(2);
  const vy = read(3);
  const height = read(4);

  const hipA = read(5);
  const hipASpeed = read(6);
  const kneeA = read(7);
  const kneeASpeed = read(8);
  const footA = read(9) > 0.5;

  const hipB = read(10);
  const hipBSpeed = read(11);
  const kneeB = read(12);
  const kneeBSpeed = read(13);
  const footB = read(14) > 0.5;

