    mem._gStartHA + startup * (refA[0] - mem._gStartHA);
  const targetKA =
    mem._gStartKA + startup * (refA[1] - mem._gStartKA);
  const targetHB =
    mem._gStartHB + startup * (refB[0] - mem._gStartHB);
