      best = { x: x.slice(), f: item.f };
    }
    return item;
  }

  const budget = remaining();
  if (budget <= 0) return encode(base);

  for (let i = 0; i < seeds.length && remaining() > 0; i++) {
    evaluate(seeds[i]);
  }

  if (!best) return encode(base);

  function identity() {
    const C = new Array(dim);
    for (let i = 0; i < dim; i++) {
      C[i] = new Array(dim).fill(0);
      C[i][i] = 1;
    }
    return C;
  }

  function eigSym(C) {
    const A = C.map((row) => row.slice());
    const B = identity();

    for (let sweep = 0; sweep < 9; sweep++) {
      let maxOff = 0;

      for (let p = 0; p < dim - 1; p++) {
        for (let q = p + 1; q < dim; q++) {
          const apq = A[p][q];
          const absq = Math.abs(apq);
          if (absq > maxOff) maxOff = absq;
          if (absq < 1e-12) continue;

          const app = A[p][p];
          const aqq = A[q][q];
          const theta = 0.5 * Math.atan2(2 * apq, aqq - app);
          const c = Math.cos(theta);
          const s = Math.sin(theta);

          for (let k = 0; k < dim; k++) {
            if (k === p || k === q) continue;
            const akp = A[k][p];
            const akq = A[k][q];
            const np = c * akp - s * akq;
            const nq = s * akp + c * akq;
            A[k][p] = np;
            A[p][k] = np;
            A[k][q] = nq;
            A[q][k] = nq;
          }

          A[p][p] = c * c * app - 2 * s * c * apq + s * s * aqq;
          A[q][q] = s * s * app + 2 * s * c * apq + c * c * aqq;
          A[p][q] = 0;
          A[q][p] = 0;

          for (let k = 0; k < dim; k++) {
            const vip = B[k][p];
            const viq = B[k][q];
            B[k][p] = c * vip - s * viq;
            B[k][q] = s * vip + c * viq;
          }
        }
      }

      if (maxOff < 1e-10) break;
    }

    const D = new Array(dim);
    for (let i = 0; i < dim; i++) {
      D[i] = Math.sqrt(Math.max(0.0001, A[i][i]));
    }
    return { B: B, D: D };
  }

  const lambda = 20;
  const mu = 10;
  const weights = new Array(mu);
  let weightSum = 0;
  for (let i = 0; i < mu; i++) {
    weights[i] = Math.log(mu + 0.5) - Math.log(i + 1);
    weightSum += weights[i];
  }
  for (let i = 0; i < mu; i++) weights[i] /= weightSum;

  let muEffInv = 0;
  for (let i = 0; i < mu; i++) muEffInv += weights[i] * weights[i];
  const muEff = 1 / muEffInv;
  const n = dim;
  const cSigma = (muEff + 2) / (n + muEff + 5);
  const dSigma =
    1 +
    2 * Math.max(0, Math.sqrt((muEff - 1) / (n + 1)) - 1) +
    cSigma;
  const cC =
    (4 + muEff / n) /
    (n + 4 + 2 * muEff / n);
  const c1 = 2 / ((n + 1.3) * (n + 1.3) + muEff);
  const cMu = Math.min(
    1 - c1,
    2 * (muEff - 2 + 1 / muEff) / ((n + 2) * (n + 2) + muEff)
  );
  const chiN =
    Math.sqrt(n) * (1 - 1 / (4 * n) + 1 / (21 * n * n));

  let mean = best.x.slice();
  let sigma = 0.24;
  let C = identity();
  let pathSigma = new Array(dim).fill(0);
  let pathC = new Array(dim).fill(0);
  let generation = 0;
  let stall = 0;
  let restarts = 0;

  while (remaining() > 0) {
    const left = remaining();
    if (left < lambda) {
      for (let k = 0; k < left && remaining() > 0; k++) {
        const candidate = new Array(dim);
        for (let j = 0; j < dim; j++) {
          candidate[j] = reflect(best.x[j] + sigma * normal());
        }
        evaluate(candidate);
      }
      break;
    }

    const bestBefore = best.f;
    const eig = eigSym(C);
    const B = eig.B;
    const D = eig.D;
    const population = [];

    for (let k = 0; k < lambda && remaining() > 0; k++) {
      const z = new Array(dim);
      for (let j = 0; j < dim; j++) z[j] = normal();

      const candidate = new Array(dim);
      const yActual = new Array(dim);

      for (let i = 0; i < dim; i++) {
        let step = 0;
        for (let j = 0; j < dim; j++) {
          step += B[i][j] * D[j] * z[j];
        }
        candidate[i] = reflect(mean[i] + sigma * step);
        yActual[i] = (candidate[i] - mean[i]) / Math.max(1e-8, sigma);
      }

      const item = evaluate(candidate);
      item.y = yActual;
      population.push(item);
    }

    if (population.length < mu) break;
    population.sort((a, b) => b.f - a.f);

    const oldMean = mean.slice();
    const newMean = new Array(dim).fill(0);
    for (let k = 0; k < mu; k++) {
      for (let i = 0; i < dim; i++) {
        newMean[i] += weights[k] * population[k].x[i];
      }
    }

    const yWeighted = new Array(dim);
    for (let i = 0; i < dim; i++) {
      yWeighted[i] =
        (newMean[i] - oldMean[i]) / Math.max(1e-8, sigma);
    }

    const projected = new Array(dim).fill(0);
    for (let j = 0; j < dim; j++) {
      for (let i = 0; i < dim; i++) {
        projected[j] += B[i][j] * yWeighted[i];
      }
      projected[j] /= D[j];
    }

    const invSqrtY = new Array(dim).fill(0);
    for (let i = 0; i < dim; i++) {
      for (let j = 0; j < dim; j++) {
        invSqrtY[i] += B[i][j] * projected[j];
      }
    }

    for (let i = 0; i < dim; i++) {
      pathSigma[i] =
        (1 - cSigma) * pathSigma[i] +
        Math.sqrt(cSigma * (2 - cSigma) * muEff) * invSqrtY[i];
    }

    let psNorm2 = 0;
    for (let i = 0; i < dim; i++) psNorm2 += pathSigma[i] * pathSigma[i];
    const psNorm = Math.sqrt(psNorm2);
    const hDenom = Math.sqrt(
      Math.max(1e-12, 1 - Math.pow(1 - cSigma, 2 * (generation + 1)))
    );
    const hSig =
      psNorm / hDenom / chiN < 1.4 + 2 / (n + 1) ? 1 : 0;

    for (let i = 0; i < dim; i++) {
      pathC[i] =
        (1 - cC) * pathC[i] +
        hSig * Math.sqrt(cC * (2 - cC) * muEff) * yWeighted[i];
    }

    const nextC = new Array(dim);
    const oldFactor =
      1 - c1 - cMu + c1 * (1 - hSig) * cC * (2 - cC);

    for (let i = 0; i < dim; i++) {
      nextC[i] = new Array(dim);
      for (let j = 0; j < dim; j++) {
        let rankMu = 0;
        for (let k = 0; k < mu; k++) {
          rankMu += weights[k] * population[k].y[i] * population[k].y[j];
        }
        nextC[i][j] =
          oldFactor * C[i][j] +
          c1 * pathC[i] * pathC[j] +
          cMu * rankMu;
      }
    }

    C = nextC;
    mean = newMean;
    sigma *= Math.exp(
      (cSigma / dSigma) * (psNorm / chiN - 1)
    );
    sigma = clamp(sigma, 0.025, 0.55);
    generation++;

    if (best.f > bestBefore + 1e-9) {
      stall = 0;
    } else {
      stall++;
    }

    if (stall >= 18 && restarts < 2 && remaining() >= lambda) {
      const pick = archive.length > 1
        ? archive[Math.min(restarts + 1, archive.length - 1)]
        : best;
      mean = (pick || best).x.slice();
      C = identity();
      pathSigma = new Array(dim).fill(0);
      pathC = new Array(dim).fill(0);
      sigma = 0.28;
      generation = 0;
      stall = 0;
      restarts++;
    }
  }

  return best ? best.x.slice() : encode(base);
}

function policy(obs, params, mem) {
