  const obstacleKnee = dec(18, 0, 6, 4.0);
  const obstacleHip = dec(19, 0, 1, 0.45);
  const contactBlend = dec(20, 0, 1, 0.40);
  const heightGain = dec(21, 0, 0.8, 0.40);
  const phaseOffset = dec(22, 0, 0.5, 0.02);
  const phaseSep = dec(23, 0.44, 0.56, 0.5);
