    mem._autoStage = 0;
    mem._autoSum0 = 0;
    mem._autoTime0 = 0;
    mem._testSum = 0;
    mem._testTime = 0;
    mem._oldAverage = 0;
    mem._flipT = -1000;
    mem._revertT = -1000;
  } else {
    const alpha = 1 - Math.exp(-dt / 0.38);
    mem._vxEMA += alpha * (vx - mem._vxEMA);

