      3.55, 0.78, 6.4, 0.73, 0.55, 0.08, -0.038, 1,
      0.80, 0.03, 0.0, 0.05, 2.8, 0.0, 0.0, 0.25,
      0.00, 0.50, 1, 0, 0.03, 0, 0.35, 0.04
    ],
    [
      0.60, 0.60, 0.70, -0.015, -0.12, -1.35,
      4.2, 0.42, 4.1, 0.42, 2.4, 0.70, -0.04, 1,
      0.78, 0.18, 0.48, 0.65, 4.0, 0.45, 0.42, 0.38,
      0.025, 0.50, 1, 1, 0.055, 0, 0.68, 0.04
    ],
    [
      0.56, 0.64, 0.84, -0.035, -0.10, -1.55,
      4.6, 0.36, 4.8, 0.38, 2.0, 0.60, -0.045, 1,
      0.90, 0.20, 0.60, 0.72, 4.8, 0.55, 0.25, 0.45,
      0.04, 0.50, 1, 1, 0.08, 0.12, 0.72, 0.05
    ],
    [
      0.64, 0.61, 0.68, -0.04, -0.10, -1.40,
      4.5, 0.50, 4.2, 0.50, 3.8, 1.40, -0.04, 1,
      0.80, 0.20, 0.75, 0.75, 4.0, 0.55, 0.35, 0.45,
      0.025, 0.48, 1, 1, 0.08, 0.05, 0.65, 0.06
    ],
    [
      0.74, 0.67, 0.58, 0.00, -0.12, -1.05,
      3.7, 0.50, 3.8, 0.48, 3.2, 0.95, -0.04, 1,
      0.65, 0.12, 0.55, 0.80, 3.4, 0.40, 0.50, 0.50,
      0.04, 0.50, 1, 0, 0.06, 0, 0.65, 0.05
    ],
    [
      0.43, 0.56, 0.86, 0.00, -0.10, -1.55,
      5.0, 0.35, 5.0, 0.36, 2.0, 0.55, -0.04, 1,
      1.05, 0.28, 0.75, 0.72, 5.0, 0.55, 0.35, 0.48,
      0.06, 0.48, 1, 1, 0.10, 0.12, 0.78, 0.05
    ],
    [
      0.82, 0.70, 0.55, -0.02, -0.18, -1.25,
      3.2, 0.65, 4.5, 0.55, 3.5, 1.20, -0.07, 1,
      0.80, 0.10, 0.30, 0.80, 3.5, 0.30, 0.40, 0.50,
      0.10, 0.52, 1, 1, 0.08, -0.08, 0.60, 0.05
    ]
  ];

  const seeds = [];
  for (let b = 0; b < bases.length; b++) {
    for (let d = 0; d < 2; d++) {
      for (let s = 0; s < 2; s++) {
        for (let a = 0; a < 2; a++) {
          const v = bases[b].slice();
          v[13] = d === 0 ? -1 : 1;
          v[24] = s === 0 ? -1 : 1;
          v[25] = a;
          seeds.push(encode(v));
        }
      }
    }
  }

  for (let i = seeds.length - 1; i > 0; i--) {
    const j = Math.floor(Math.random() * (i + 1));
    const tmp = seeds[i];
    seeds[i] = seeds[j];
    seeds[j] = tmp;
  }

  let used = 0;
  let best = null;
  const archive = [];

  function remaining() {
    let n = Math.max(0, 1000 - used);
    try {
      const q =
        typeof lab.trialsLeft === "function"
          ? Number(lab.trialsLeft())
          : Number(lab.trialsLeft);
      if (isFinite(q)) n = Math.min(n, Math.max(0, Math.floor(q)));
    } catch (e) {}
    return n;
  }

  function remember(item) {
    let near = -1;
    let nearD = Infinity;

    for (let k = 0; k < archive.length; k++) {
      let d2 = 0;
      for (let j = 0; j < dim; j++) {
        const d = item.x[j] - archive[k].x[j];
        d2 += d * d;
      }
      const d = Math.sqrt(d2 / dim);
      if (d < nearD) {
        nearD = d;
        near = k;
      }
    }

    if (near >= 0 && nearD < 0.075) {
      if (item.f > archive[near].f) {
        archive[near] = { x: item.x.slice(), f: item.f };
      }
    } else {
      archive.push({ x: item.x.slice(), f: item.f });
    }

    archive.sort((a, b) => b.f - a.f);
    if (archive.length > 18) archive.length = 18;
  }

  function evaluate(candidate) {
    const x = new Array(dim);
    for (let i = 0; i < dim; i++) x[i] = reflect(candidate[i]);

    let r = null;
    try {
      r = lab.trial(x.slice());
    } catch (e) {
      r = null;
    }
    used++;

    const distance =
      r && typeof r.distance === "number" && isFinite(r.distance)
        ? r.distance
        : -1000;
    let time =
      r && typeof r.time === "number" && isFinite(r.time)
        ? clamp(r.time, 0, 10)
        : 0;
    const outcome = r && r.outcome;
    if (outcome === "finished" && time <= 0) time = 10;

    let fitness = distance + 0.055 * time;
    if (outcome === "finished") fitness += 0.18;
    if (outcome === "fell") fitness -= 0.03;
    if (!r || outcome === "invalid" || outcome === "error") {
      fitness = -100000;
    }

    const item = { x: x, f: fitness };
    remember(item);
    if (!best || item.f > best.f) {
      best = { x: x.slice(), f: fitness };
    }
    return item;
  }

  const budget = remaining();
  if (budget <= 0) return encode(bases[0]);

  const pop = [];
  const popSize = Math.min(80, budget);
  for (let i = 0; i < popSize && remaining() > 0; i++) {
    pop.push(evaluate(seeds[i % seeds.length]));
  }
  if (pop.length === 0) return encode(bases[0]);

  const weights = [
    1.2, 0.9, 1.15, 0.65, 0.75, 0.9, 0.8, 0.7, 0.65, 0.7,
    0.85, 0.8, 0.55, 0.55, 0.65, 0.6, 0.65, 0.45, 0.45, 0.35,
    0.4, 0.5, 0.3, 0.25, 0.45, 0.25, 0.55, 0.4, 0.6, 0.35
  ];
  let weightSum = 0;
  for (let i = 0; i < weights.length; i++) weightSum += weights[i];

  const pickDimension = () => {
    let q = Math.random() * weightSum;
    for (let i = 0; i < weights.length; i++) {
      q -= weights[i];
      if (q <= 0) return i;
    }
    return dim - 1;
  };

  let sinceBest = 0;

  while (remaining() > 0 && pop.length > 0) {
    const oldBest = best ? best.f : -Infinity;
    const progress = used / Math.max(1, budget);
    const ranked = pop.slice().sort((a, b) => b.f - a.f);

    let targetIndex = 0;
    let candidate;
    const mode = Math.random();
    const doLocal = mode < 0.55 || pop.length < 4;
    const doDE = !doLocal && mode < 0.90 && pop.length >= 4;

    if (doLocal) {
      const worst = ranked[ranked.length - 1];
      targetIndex = pop.indexOf(worst);
      if (targetIndex < 0) targetIndex = 0;

      let parent;
      if (archive.length > 0 && Math.random() < 0.75) {
        parent = archive[Math.floor(Math.random() * Math.min(8, archive.length))].x;
      } else {
        parent = ranked[
          Math.floor(Math.random() * Math.min(12, ranked.length))
        ].x;
      }

      candidate = parent.slice();
      const count = 1 + Math.floor(Math.random() * 5);
      const sigma =
        (0.035 + 0.14 * (1 - progress)) * (sinceBest > 100 ? 1.35 : 1);
      const selected = [];

      for (let k = 0; k < count; k++) {
        let j = pickDimension();
        let tries = 0;
        while (selected.indexOf(j) >= 0 && tries++ < 35) j = pickDimension();
        if (selected.indexOf(j) >= 0) continue;
        selected.push(j);

        if (categorical.indexOf(j) >= 0) {
          candidate[j] =
            candidate[j] < 0 ? 1 : (candidate[j] > 0 ? -1 : (Math.random() < 0.5 ? -1 : 1));
        } else {
          candidate[j] = reflect(candidate[j] + sigma * normal());
        }
      }
    } else if (doDE) {
      targetIndex = Math.floor(Math.random() * pop.length);
      const topCount = Math.min(10, ranked.length);
      const pbest = ranked[Math.floor(Math.random() * topCount)].x;
      const current = pop[targetIndex].x;

      let r1 = Math.floor(Math.random() * pop.length);
      let guard = 0;
      while (r1 === targetIndex && guard++ < 30) {
        r1 = Math.floor(Math.random() * pop.length);
      }
      let r2 = Math.floor(Math.random() * pop.length);
      guard = 0;
      while ((r2 === targetIndex || r2 === r1) && guard++ < 30) {
        r2 = Math.floor(Math.random() * pop.length);
      }

      const F = 0.35 + 0.48 * Math.random();
      const CR = 0.12 + 0.48 * Math.random();
      const forced = Math.floor(Math.random() * dim);
      candidate = new Array(dim);

      for (let j = 0; j < dim; j++) {
        if (Math.random() < CR || j === forced) {
          if (categorical.indexOf(j) >= 0) {
            candidate[j] = Math.random() < 0.55 ? pbest[j] : current[j];
            if (Math.random() < 0.08) candidate[j] = -candidate[j];
          } else {
            const mutant =
              current[j] +
              F * (pbest[j] - current[j]) +
              F * (pop[r1].x[j] - pop[r2].x[j]);
            candidate[j] = reflect(mutant);
          }
        } else {
          candidate[j] = current[j];
        }
      }
    } else {
      const source =
        archive.length > 0 && Math.random() < 0.7
          ? archive[Math.floor(Math.random() * Math.min(10, archive.length))].x
          : seeds[Math.floor(Math.random() * seeds.length)];
      targetIndex = pop.indexOf(ranked[ranked.length - 1]);
      if (targetIndex < 0) targetIndex = 0;

      candidate = new Array(dim);
      const sigma = 0.10 + 0.28 * Math.random();
      for (let j = 0; j < dim; j++) {
        if (categorical.indexOf(j) >= 0) {
          candidate[j] = Math.random() < 0.5 ? -1 : 1;
        } else if (Math.random() < 0.18) {
          candidate[j] = 2 * Math.random() - 1;
        } else {
          candidate[j] = reflect(source[j] + sigma * normal());
        }
      }
    }

    const result = evaluate(candidate);
    if (result.f > pop[targetIndex].f + 1e-10) {
      pop[targetIndex] = result;
    } else {
      let worstIndex = 0;
      for (let i = 1; i < pop.length; i++) {
        if (pop[i].f < pop[worstIndex].f) worstIndex = i;
      }
      if (result.f > pop[worstIndex].f + 1e-10) pop[worstIndex] = result;
    }

    if (best && best.f > oldBest + 1e-10) {
      sinceBest = 0;
    } else {
      sinceBest++;
    }
  }

  return best ? best.x.slice() : encode(bases[0]);
}

function policy(obs, params, mem) {
  if (!obs || typeof obs.length !== "number") obs = [];
  if (!mem || typeof mem !== "object") mem = {};

  const clamp = (x, lo, hi) => Math.max(lo, Math.min(hi, x));
  const fract = (x) => x - Math.floor(x);
  const smooth = (x) => {
    x = clamp(x, 0, 1);
    return x * x * (3 - 2 * x);
  };
  const read = (i) => {
    const x = obs[i];
    return typeof x === "number" && isFinite(x) ? x : 0;
  };

  const z = params && typeof params.length === "number" ? params : [];
  const dec = (i, lo, hi, fallback) => {
    const x = z[i];
    if (typeof x !== "number" || !isFinite(x)) return fallback;
    return lo + 0.5 * (clamp(x, -1, 1) + 1) * (hi - lo);
  };

  const period = dec(0, 0.42, 0.90, 0.64);
  const duty = dec(1, 0.50, 0.76, 0.62);
  const amp = dec(2, 0.25, 0.90, 0.62);
  const center = dec(3, -0.16, 0.16, 0);
  const kneeStance = dec(4, -0.25, -0.035, -0.10);
  const kneeFlex = dec(5, -1.68, -0.55, -1.25);
  const hipKp = dec(6, 1.0, 7.0, 4.5);
  const hipKd = dec(7, 0.04, 1.10, 0.48);
  const kneeKp = dec(8, 1.0, 7.0, 4.6);
  const kneeKd = dec(9, 0.04, 1.10, 0.46);
  const balanceKp = dec(10, 0.15, 5.5, 2.8);
  const balanceKd = dec(11, 0.02, 1.9, 0.80);
  const leanAim = dec(12, -0.18, 0.08, -0.04);
  const initialDirection =
    typeof z[13] === "number" && z[13] < 0 ? -1 : 1;
  const targetSpeed = dec(14, 0.10, 1.40, 0.72);
  const strideAdapt = dec(15, 0, 0.50, 0.16);
  const catchGain = dec(16, 0, 1.20, 0.65);
  const supportBias = dec(17, 0, 1, 0.70);
  const obstacleKnee = dec(18, 0, 6, 4.0);
  const heightGain = dec(19, 0, 0.90, 0.45);
  const phaseOffset = dec(20, 0, 0.50, 0.05);
  const balanceSign =
    typeof z[21] === "number" && z[21] < 0 ? -1 : 1;
  const velocityLean = dec(22, 0, 0.25, 0.07);
  const stanceDrive = dec(23, -0.45, 0.45, 0);
  const recoveryPriority = dec(24, 0, 1.5, 1.0);

  const torsoAngle = read(0);
  const torsoSpin = read(1);
  const vx = read(2);
  const vy = read(3);
  const height = read(4);

  const hipA = read(5);
  const hipASpeed = read(6);
  const kneeA = read(7);
  const kneeASpeed = read(8);
  const footA = read(9) > 0.5;

  const hipB = read(10);
  const hipBSpeed = read(11);
  const kneeB = read(12);
  const kneeBSpeed = read(13);
  const footB = read(14) > 0.5;

  const t = Math.max(0, read(19));
  const first = mem._gInit !== 1;

  let dt = 1 / 60;
  if (!first) {
    let elapsed = t - mem._lastT;
    if (!(elapsed > 0) || !isFinite(elapsed)) elapsed = 1 / 60;
    dt = clamp(elapsed, 1 / 240, 0.08);
  }

  if (first) {
    mem._vxEMA = vx;
    mem._dirSum = 0;
    mem._dirTime = 0;
    mem._didFlip = 0;
    mem._dirFlipT = -1000;
  } else {
    const alpha = 1 - Math.exp(-dt / 0.38);
    mem._vxEMA += alpha * (vx - mem._vxEMA);

    if (t > 0.35 && mem._didFlip !== 1) {
      mem._dirSum += vx * dt;
      mem._dirTime += dt;

      const meanV =
        mem._dirTime > 0 ? mem._dirSum / mem._dirTime : mem._vxEMA;
      if (
        t > 1.30 &&
        mem._dirTime > 0.75 &&
        meanV < -0.18 &&
        mem._vxEMA < -0.12
      ) {
        mem._didFlip = 1;
        mem._dirFlipT = t;
      }
    }
  }

  let directionFactor = 1;
  if (mem._didFlip === 1) {
    directionFactor = 1 - 2 * smooth((t - mem._dirFlipT) / 0.30);
  }
  const direction = initialDirection * directionFactor;

  const speedError = clamp(targetSpeed - vx, -1.5, 1.5);
  const strideScale = clamp(1 + strideAdapt * speedError, 0.72, 1.40);
  const effectiveAmp = clamp(amp * strideScale, 0.25, 1.02);
  const cadence = clamp(1 + 0.12 * strideAdapt * speedError, 0.82, 1.18);
  const effectivePeriod = clamp(period / cadence, 0.34, 1.15);

  const hipFront = clamp(center + direction * effectiveAmp, -0.88, 1.18);
  const hipBack = clamp(center - direction * effectiveAmp, -0.88, 1.18);

  const a1 = read(15);
  const a2 = read(16);
  const a3 = read(17);
  const a4 = read(18);
  const hazard = clamp(
    Math.max(
      0,
      a1 - 0.025,
      0.78 * (a2 - 0.025),
      0.52 * (a3 - 0.025),
      0.28 * (a4 - 0.025)
    ),
    0,
    0.34
  );

  const desiredLean = clamp(
    leanAim - velocityLean * speedError,
    -0.24,
    0.12
  );
  const angleError = clamp(torsoAngle - desiredLean, -1.5, 1.5);
  const spin = clamp(torsoSpin, -12, 12);
  const catchSignal = clamp(
    -torsoAngle - 0.16 * spin + 0.05 * speedError,
    -1,
    1
  );

  const heightError = clamp(
    1.07 - height - 0.045 * vy,
    -0.30,
    0.30
  );
  const low = smooth((1.02 - height) / 0.22);
  const severity = smooth(
    (Math.abs(angleError) + 0.035 * Math.min(Math.abs(spin), 8) - 0.12) /
      0.48
  );

  const stanceK = clamp(
    kneeStance + heightGain * (heightError + 0.06 * low),
    -1.68,
    -0.055
  );
  const catchShift = clamp(
    catchGain * catchSignal * (1 + 0.70 * severity + 0.35 * low),
    -0.85,
    0.85
  );

  let pa, pb;
  if (first) {
    if (footA && !footB) {
      pa = 0.05;
      pb = fract(pa + 0.50);
    } else if (footB && !footA) {
      pb = 0.05;
      pa = fract(pb + 0.50);
    } else if (footA && footB) {
      pa = 0.10;
      pb = 0.60;
    } else {
      pa = fract(phaseOffset);
      pb = fract(pa + 0.50);
    }

    mem._startHA = hipA;
    mem._startKA = kneeA;
    mem._startHB = hipB;
    mem._startKB = kneeB;
    mem._prevHA = hipA;
    mem._prevKA = kneeA;
    mem._prevHB = hipB;
    mem._prevKB = kneeB;
  } else {
    pa = fract(mem._gPA + dt / effectivePeriod);
    pb = fract(mem._gPB + dt / effectivePeriod);

    const touchPhase = Math.max(0.48, duty - 0.08);
    if (footA && !mem._footA && pa > touchPhase) pa = 0.01;
    if (footB && !mem._footB && pb > touchPhase) pb = 0.01;
  }

  function targets(p, foot) {
    let h, k;

    if (p < duty) {
      const u = clamp(p / duty, 0, 1);
      h = hipFront + (hipBack - hipFront) * smooth(u);
      k = stanceK;
      h += direction * catchShift * (foot ? 0.16 : 0.34);
    } else {
      const u = clamp((p - duty) / (1 - duty), 0, 1);
      const s = Math.sin(Math.PI * u);
      const lift = s * s;

      h = hipBack + (hipFront - hipBack) * smooth(u);
      h += direction * 0.42 * hazard * lift;
      h += direction * catchShift * (foot ? 0.34 : 0.82);

      k = stanceK + (kneeFlex - stanceK) * lift;
      k += 0.15 * heightGain * heightError;
      k -= obstacleKnee * hazard * lift;

      if (foot) {
        const alpha = 0.56 * (1 - smooth(u / 0.45));
        k += (stanceK - k) * alpha;
      }
    }

    return [
      clamp(h, -0.88, 1.18),
      clamp(k, -1.68, -0.055)
    ];
  }

  const refA = targets(pa, footA);
  const refB = targets(pb, footB);
  const startup = smooth(t / 0.14);

  const targetHA =
    mem._startHA + startup * (refA[0] - mem._startHA);
  const targetKA =
    mem._startKA + startup * (refA[1] - mem._startKA);
  const targetHB =
    mem._startHB + startup * (refB[0] - mem._startHB);
  const targetKB =
    mem._startKB + startup * (refB[1] - mem._startKB);

  let vHA = 0, vKA = 0, vHB = 0, vKB = 0;
  if (!first) {
    vHA = clamp((targetHA - mem._prevHA) / dt, -8, 8);
    vKA = clamp((targetKA - mem._prevKA) / dt, -8, 8);
    vHB = clamp((targetHB - mem._prevHB) / dt, -8, 8);
    vKB = clamp((targetKB - mem._prevKB) / dt, -8, 8);
  }

  mem._prevHA = targetHA;
  mem._prevKA = targetKA;
  mem._prevHB = targetHB;
  mem._prevKB = targetKB;

  let balance =
    balanceSign * (balanceKp * angleError + balanceKd * spin);
  balance *= 1 + recoveryPriority * (0.42 * severity + 0.28 * low);
  if (!footA && !footB) balance *= 0.82;
  balance = clamp(balance, -1.70, 1.70);

  const stanceA = pa < duty;
  const stanceB = pb < duty;
  const wa = 0.22 + supportBias * (footA ? 1.0 : (stanceA ? 0.40 : 0.10));
  const wb = 0.22 + supportBias * (footB ? 1.0 : (stanceB ? 0.40 : 0.10));
  const balanceA = balance * (2 * wa / Math.max(0.01, wa + wb));
  const balanceB = balance * (2 * wb / Math.max(0.01, wa + wb));

  const recoveryMix = clamp(
    recoveryPriority * (0.10 * severity + 0.30 * low),
    0,
    0.62
  );
  const trackScale = 1 - recoveryMix;

  const driveA =
    stanceDrive *
    clamp(speedError, -1.2, 1.2) *
    (footA ? 1.0 : (stanceA ? 0.48 : 0.04));
  const driveB =
    stanceDrive *
    clamp(speedError, -1.2, 1.2) *
    (footB ? 1.0 : (stanceB ? 0.48 : 0.04));

  const uHA =
    trackScale *
      (hipKp * (targetHA - hipA) +
        hipKd * (0.68 * vHA - clamp(hipASpeed, -20, 20))) +
    balanceA +
    driveA;
  const uKA =
    kneeKp * (targetKA - kneeA) +
    kneeKd * (0.68 * vKA - clamp(kneeASpeed, -20, 20)) +
    low * recoveryPriority * (footA ? 0.12 : -0.035);
  const uHB =
    trackScale *
      (hipKp * (targetHB - hipB) +
        hipKd * (0.68 * vHB - clamp(hipBSpeed, -20, 20))) +
    balanceB +
    driveB;
  const uKB =
    kneeKp * (targetKB - kneeB) +
    kneeKd * (0.68 * vKB - clamp(kneeBSpeed, -20, 20)) +
    low * recoveryPriority * (footB ? 0.12 : -0.035);

  mem._gPA = pa;
  mem._gPB = pb;
  mem._footA = footA;
  mem._footB = footB;
  mem._lastT = t;
  mem._gInit = 1;

  return [
    clamp(uHA, -1, 1),
    clamp(uKA, -1, 1),
    clamp(uHB, -1, 1),
    clamp(uKB, -1, 1)
  ];
}

function learn(lab) {
  const lo = [
    0.42, 0.50, 0.25, -0.16, -0.25, -1.68,
    1.0, 0.04, 1.0, 0.04, 0.15, 0.02,
    -0.18, -1, 0.10, 0, 0, 0, 0, 0,
    0, -1, 0, -0.45, 0
  ];
  const hi = [
    0.90, 0.76, 0.90, 0.16, -0.035, -0.55,
    7.0, 1.10, 7.0, 1.10, 5.5, 1.9,
    0.08, 1, 1.40, 0.50, 1.20, 1, 6, 0.90,
    0.50, 1, 0.25, 0.45, 1.5
  ];
