  const fLean = num('fLean', 0);
  const vRef = num('vRef', 2);
  const dv = clamp(vx - vRef, -2, 2);
  const freq = clamp(f + fv * (vx - 2) + fLean * torsoAngle, 0.3, 5);
  mem.ph += 2 * Math.PI * freq * dt;
  if (mem.ph > 1e6) mem.ph = mem.ph % (2 * Math.PI);

  const dphi = num('dphi', Math.PI);
  const hOff = num('hOff', 0);
  const hAmp = num('hAmp', 0.5);
  const hAmp2 = num('hAmp2', 0);
  const hPsi = num('hPsi', 0);
  const bal = num('bal', 0);
  const balD = num('balD', 0);
  const balV = num('balV', 0);
  const lean0 = num('lean', 0);
  const leanV = num('leanV', 0);
  const lean = lean0 + leanV * dv;
  const kOff = num('kOff', -0.9);
  const kAmp = num('kAmp', 0.6);
  const kLead = num('kLead', 0);
  const kBal = num('kBal', 0);
  const kneeV = num('kneeV', 0);
  const kp = num('kp', 6);
  const kd = num('kd', 0.3);
  const hGain = num('hGain', 1.5);
  const hLift = num('hLift', 0);

  const balance = clamp(bal * (torsoAngle - lean) + balD * torsoSpin + balV * dv, -0.8, 0.8);
  const ahead = Math.max(a1, 0.85 * a2, 0.7 * a3);
  const flex = clamp(hGain * ahead, 0, 0.8);
  const lift = clamp(hLift * ahead, -0.6, 0.6);
  const kneeSpeed = kneeV * dv;

  const legs = [
    { hip: o(5), hipV: o(6), knee: o(7), kneeV: o(8), ph: mem.ph },
    { hip: o(10), hipV: o(11), knee: o(12), kneeV: o(13), ph: mem.ph + dphi }
  ];

  const out = [];
  for (let i = 0; i < 2; i++) {
    const L = legs[i];
    const s = Math.sin(L.ph);
    const hipT = clamp(hOff + hAmp * s + hAmp2 * Math.sin(2 * L.ph + hPsi) + balance + lift, -0.85, 1.15);
    const kneeT = clamp(kOff + kneeSpeed - kAmp * Math.max(0, Math.sin(L.ph + kLead)) - kBal * (torsoAngle - lean) - flex, -1.65, -0.1);
    const hipU = clamp(kp * (hipT - L.hip) - kd * L.hipV, -1, 1);
    const kneeU = clamp(kp * (kneeT - L.knee) - kd * L.kneeV, -1, 1);
    out.push(hipU, kneeU);
  }
  return out;
}

function learn(lab) {
  const spec = {
    f: [0.8, 4.5], fv: [-0.15, 0.15], dphi: [2.0, 4.3], hOff: [-0.4, 0.4], hAmp: [0, 0.9],
    hAmp2: [-0.3, 0.3], hPsi: [-3.14, 3.14],
    bal: [-3, 3], balD: [-0.5, 0.5], balV: [-0.5, 0.5], vRef: [0, 4], lean: [-0.3, 0.3],
    kOff: [-1.5, -0.3], kAmp: [0, 1.2], kLead: [-1.5, 1.5], kBal: [-0.5, 0.5],
    kp: [2, 15], kd: [0, 1.2], hGain: [0, 2], hLift: [-0.6, 0.6], fLean: [-0.5, 0.5],
    leanV: [-0.2, 0.2], kneeV: [-0.5, 0.5]
  };
  const keys = Object.keys(spec);
  const n = keys.length;
  const lo = keys.map((k) => spec[k][0]);
  const span = keys.map((k) => spec[k][1] - spec[k][0]);

  const now = () => (typeof Date !== 'undefined' && Date.now) ? Date.now() : 0;
  const t0 = now();
  const timeLeft = () => (now() - t0) < 150000;
  const canTrial = () => {
    if (!timeLeft()) return false;
    try { return lab.trialsLeft() > 0; } catch (e) { return archive.length < 900; }
  };
  const gauss = () => Math.sqrt(-2 * Math.log(Math.random() + 1e-12)) * Math.cos(2 * Math.PI * Math.random());
  const clamp01 = (x) => x.map((v) => (v < 0 ? 0 : (v > 1 ? 1 : v)));
  const toP = (x) => { const r = {}; for (let i = 0; i < n; i++) r[keys[i]] = lo[i] + x[i] * span[i]; return r; };
  const toX = (q) => keys.map((k, i) => {
    const v = (q && typeof q[k] === 'number' && isFinite(q[k])) ? q[k] : lo[i] + span[i] / 2;
    return (v - lo[i]) / span[i];
  });

  const archive = [];
  let best = null;
  let bestScore = -Infinity;
  let bestX = null;

  const evalX = (x) => {
    const xc = clamp01(x);
    const p = toP(xc);
    let score = -1;
    try {
      const r = lab.trial(p);
      if (r && r.outcome !== 'error' && r.outcome !== 'invalid' &&
          typeof r.distance === 'number' && isFinite(r.distance)) {
        score = r.distance + (r.outcome === 'finished' ? 3 : 0);
      }
    } catch (e) {
      score = -1;
    }
    const entry = { x: xc, p: p, s: score };
    archive.push(entry);
    if (score > bestScore) { bestScore = score; best = p; bestX = xc; }
    return entry;
  };

  const cmaRun = (x0, sigma0, lambda) => {
    const mu = Math.floor(lambda / 2);
    const w = [];
    let sw = 0;
    for (let i = 0; i < mu; i++) { const v = Math.log(mu + 0.5) - Math.log(i + 1); w.push(v); sw += v; }
    for (let i = 0; i < mu; i++) w[i] /= sw;
    const mueff = 1 / w.reduce((a, v) => a + v * v, 0);
    const cs = (mueff + 2) / (n + mueff + 5);
    const damps = 1 + 2 * Math.max(0, Math.sqrt((mueff - 1) / (n + 1)) - 1) + cs;
    const chiN = Math.sqrt(n) * (1 - 1 / (4 * n) + 1 / (21 * n * n));
    const cmu = Math.min(0.3, mueff / n);

    let mean = x0.slice();
    let sigma = sigma0;
    const D = new Array(n).fill(1);
    const ps = new Array(n).fill(0);
    let runBest = -Infinity;
    let lastImp = 0;

    for (let g = 0; g < 400 && canTrial(); g++) {
      const pop = [];
      for (let k = 0; k < lambda; k++) {
        if (!canTrial()) break;
        const z = keys.map(() => gauss());
        pop.push(evalX(mean.map((m, i) => m + sigma * D[i] * z[i])));
      }
      if (pop.length < mu) break;
      pop.sort((a, b) => b.s - a.s);

      const oldMean = mean;
      const newMean = new Array(n).fill(0);
      for (let i = 0; i < mu; i++) for (let j = 0; j < n; j++) newMean[j] += w[i] * pop[i].x[j];

      let ps2 = 0;
      for (let j = 0; j < n; j++) {
        const y = (newMean[j] - oldMean[j]) / sigma;
        ps[j] = (1 - cs) * ps[j] + Math.sqrt(cs * (2 - cs) * mueff) * y / D[j];
        ps2 += ps[j] * ps[j];
      }
      for (let j = 0; j < n; j++) {
        let acc = 0;
        for (let i = 0; i < mu; i++) {
          const d = (pop[i].x[j] - oldMean[j]) / sigma;
          acc += w[i] * d * d;
        }
        D[j] = Math.min(3, Math.max(0.05, Math.sqrt((1 - cmu) * D[j] * D[j] + cmu * acc)));
      }
      sigma = Math.min(0.5, sigma * Math.exp((cs / damps) * (Math.sqrt(ps2) / chiN - 1)));
      mean = clamp01(newMean);

      if (pop[0].s > runBest + 1e-9) { runBest = pop[0].s; lastImp = g; }
      if (g - lastImp > 20 || sigma < 1e-4) break;
    }
  };

  // Seeds: attempt-5 best (known 13 m gait, new terms at zero), then a slower variant
  const seedA5 = {
    f: 2.47099142446445, fv: -0.011883670388631931, dphi: 3.1850097437159257,
    hOff: -0.17306313289286301, hAmp: 0.5, hAmp2: -0.041028829155293614, hPsi: -0.008029942368405596,
    bal: -0.7303214586354573, balD: -0.08845381878315986, balV: 0.09125559083543115,
    vRef: 2.23406979010837, lean: 0.012210416059361866, kOff: -0.7004792541840456,
    kAmp: 0.75, kLead: -0.6811287750339485, kBal: -0.060805162929214514,
    kp: 6.700203190228024, kd: 0.09830023756438569, hGain: 1.4827954981416185,
    hLift: -0.061911387366533836, fLean: 0, leanV: 0, kneeV: 0
  };
  const seedSlow = Object.assign({}, seedA5, { f: 1.8, hAmp: 0.6, kAmp: 0.6, vRef: 1.5, balV: 0.2 });
  const seedA4 = {
    f: 3.1188868673788335, fv: -0.004163135379648979, dphi: 2.981741116208158,
    hOff: -0.1973234103998909, hAmp: 0.3679383855635673, bal: -0.8204423194601946,
    balD: -0.08413458621091723, balV: -0.018186806667834697, vRef: 2.223654293932796,
    lean: 0.04294731359758289, kOff: -0.5613208894627407, kAmp: 0.7006055795984063,
    kLead: -0.48517525603961653, kp: 5.675013718703414, kd: 0.040789358898948476,
    hGain: 1.5, hAmp2: 0, hPsi: 0, kBal: 0, hLift: 0, fLean: 0, leanV: 0, kneeV: 0
  };

  // Phase 1: seeds plus a broad random sample
  for (const s of [seedA5, seedSlow, seedA4]) {
    if (!canTrial()) break;
    evalX(toX(s));
  }
  for (let i = 0; i < 30 && canTrial(); i++) {
    evalX(keys.map(() => Math.random()));
  }

  // Phase 2: CMA-style restarts alternating between best point, random points, and elite archive points
  let run = 0;
  while (canTrial() && run < 300 && archive.length > 0) {
    let x0, sig, lam;
    if (run % 3 === 0 && bestX) {
      x0 = bestX; sig = 0.08; lam = 10;
    } else if (run % 3 === 1) {
      x0 = keys.map(() => Math.random()); sig = 0.3; lam = 16;
    } else {
      const top = archive.slice().sort((a, b) => b.s - a.s).slice(0, 10);
      x0 = top[Math.floor(Math.random() * top.length)].x;
      sig = 0.15; lam = 12;
    }
    cmaRun(x0, sig, lam);
    run++;
  }

  return best || seedA5;
}
